const requiredDocuments = [
  "BILL OF LADING",
  "COMMERCIAL INVOICE",
  "PACKING LIST",
  "FORM M",
  "CUSTOMS DECLARATION",
  "DELIVERY ORDER",
  "CONTAINER MANIFEST"
];

return $input.all().map(item => {
  const shipment = item.json;

  const receivedDocuments = [
    ...new Set(
      (shipment.documents_compared || [])
        .map(doc => String(doc).trim().toUpperCase())
    )
  ];

  const missingDocuments = requiredDocuments.filter(
    doc => !receivedDocuments.includes(doc)
  );

  const discrepancies = shipment.discrepancies || [];

  const ready =
    missingDocuments.length === 0 &&
    discrepancies.length === 0;

  return {
    json: {
      ...shipment,
      required_documents: requiredDocuments,
      received_documents: receivedDocuments,
      missing_documents: missingDocuments,
      missing_document_count: missingDocuments.length,
      discrepancy_count: discrepancies.length,
      validation_status: ready
        ? "DOCUMENTS VERIFIED"
        : "HUMAN REVIEW REQUIRED",
      ready_for_document_review: ready
    }
  };
});
